-- 0047: left basal ganglia, indirect pathway (the product owner's spreadsheet brain_region_new_platform_1.xlsx).
--
-- The interval line moves from the right-side diagonal (TLDBR) to the left-side pair. The spreadsheet types it as
-- "LTR, TRDBL"; TRDBL heads left, which breaks the eye-movement rule for a left-hemisphere row, so the diagonal
-- stored is BLDTR, as on the direct pathway (0045) and pending the owner's confirmation.
--
-- Data only. Generated by settingRevisionSql(); a test checks this file against it.

UPDATE app.region_setting s SET bg_temperature = 'warm', bg_types = ARRAY['textured', 'solid']::text[], motion = '[{"movement_types":[1],"directions":["ltr","bldtr"]},{"movement_types":[1],"directions":["btt"]}]'::jsonb, target_locations = ARRAY['E', 'SE', 'NE', 'N', 'S']::text[], rotation = 'ccw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'left.subcortical.basal_ganglia_indirect';
